PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE trades (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                trade_id TEXT UNIQUE NOT NULL,
                symbol TEXT NOT NULL,
                strategy TEXT NOT NULL,
                side TEXT NOT NULL, -- 'BUY' or 'SELL'
                quantity INTEGER NOT NULL,
                entry_price REAL NOT NULL,
                exit_price REAL,
                entry_time TIMESTAMP NOT NULL,
                exit_time TIMESTAMP,
                duration_minutes INTEGER,
                pnl REAL,
                commission REAL DEFAULT 0,
                status TEXT DEFAULT 'OPEN', -- 'OPEN', 'CLOSED', 'CANCELLED'
                notes TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            , confidence DECIMAL(5,2) CHECK (confidence IS NULL OR (confidence >= 0 AND confidence <= 100)), actual_entry_price REAL, actual_exit_price REAL, actual_entry_time TIMESTAMP, actual_exit_time TIMESTAMP, entry_slippage REAL, exit_slippage REAL, entry_slippage_pct REAL, exit_slippage_pct REAL, total_slippage_impact REAL, planned_pnl REAL, actual_pnl REAL, entry_filled BOOLEAN DEFAULT 0, exit_filled BOOLEAN DEFAULT 0, broker_order_id_entry TEXT, broker_order_id_exit TEXT);
COMMIT;
